info.description:
Coleção de **quality assurance (QA / contract tests)** da Base API.

Auto-configurável e repetível:
- Auto-login: o pre-request global loga com o seed (`admin`/`admin123`) quando o token está vazio;
- Resolvedores: requests que dependem de IDs já criados buscam na lista correspondente quando a variável está vazia;
- Captura de IDs: as requests de criação registram os ids criados nas variáveis da coleção;
- Dados aleatórios (`{{$randomEmail}}`, `{{$timestamp}}`...) evitam conflitos de unicidade em re-execuções.

Cada request valida:
- Status code esperado (200/201/204);
- Tempo de resposta < 2000ms;
- Content-Type `application/json` (quando aplicável);
- Formato do corpo (lista, objeto, campo obrigatório, download/arquivo).

Execute pelo **Collection Runner** do Postman ou Newman:
`newman run postman/base_api_qualidade.postman_collection.json`

Obs.: a API deve subir com o perfil `dev` para que o seed exista. Requisitos: token (auto), igrejaId/pessoaId/servicoId/escalaId/cultoId etc. (auto via resolvedores e capturas).

exec:
(function () {
    if (pm.collectionVariables.get('token')) { return; }
    var base = pm.collectionVariables.get('baseUrl') || 'http://localhost:8080';
    var req = {
        url: base + '/api/auth/login',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify({ username: 'admin', senha: 'admin123' }) }
    };
    pm.sendRequest(req, function (err, res) {
        if (err || res.code !== 200) { return; }
        var j = res.json();
        pm.collectionVariables.set('token', j.token);
    });
})();

(function () {
    var v = pm.collectionVariables.get('pessoaId');
    if (v) { return; }
    var url = pm.collectionVariables.get('baseUrl') + '/api/pessoas';
    pm.sendRequest(url, function (err, res) {
        if (err || res.code !== 200) { return; }
        var data = res.json();
        var pick = function (fieldExpr) {
            if (fieldExpr.indexOf('[') > -1) {
                var parts = fieldExpr.split('.');
                var cur = data;
                for (var i = 0; i < parts.length; i++) {
                    var idx = null;
                    var p = parts[i];
                    var m = p.match(/^(.*)\[(\d+)\]$/);
                    if (m) { p = m[1]; idx = parseInt(m[2]); }
                    cur = cur[p];
                    if (idx !== null && cur) { cur = cur[idx]; }
                }
                return cur;
            } else {
                if (Array.isArray(data) && data.length > 0) return data[0][fieldExpr];
                if (data && data[fieldExpr] !== undefined) return data[fieldExpr];
                return undefined;
            }
        };
        var val = pick('id');
        if (val) { pm.collectionVariables.set('pessoaId', val); }
    });
})();

