(function () {{
    var v = pm.collectionVariables.get('servicoId');
    if (v) {{ return; }}
    var base = pm.collectionVariables.get('baseUrl');
    var mid = pm.collectionVariables.get('ministerioId');
    var seed = pm.collectionVariables.get('igrejaId');
    var fetchServicos = function (ministerioId) {{
        pm.sendRequest(base + '/api/ministerios/' + ministerioId + '/servicos', function (err2, res2) {{
            if (err2 || res2.code !== 200) {{ return; }}
            var arr = res2.json();
            if (Array.isArray(arr) && arr.length > 0) {{
                pm.collectionVariables.set('servicoId', arr[0].id);
            }}
        }});
    }};
    if (mid) {{
        fetchServicos(mid);
    }} else {{
        pm.sendRequest(base + '/api/ministerios?igrejaId=' + seed, function (err, res) {{
            if (err || res.code !== 200) {{ return; }}
            var arr = res.json();
            if (Array.isArray(arr) && arr.length > 0) {{
                var first = arr[0].id;
                pm.collectionVariables.set('ministerioId', first);
                fetchServicos(first);
            }}
        }});
    }}
}})();

